<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';const keyword=ref('');const items=ref<any[]>([]);async function search(){items.value=(await api.schools({keyword:keyword.value,province:'河南'})).items}</script><template><section class="content-page"><div class="eyebrow">SCHOOLS / INDEX</div><h1>院校库</h1><div class="ask-row"><input v-model="keyword" placeholder="搜索院校"/><button class="primary" @click="search">检索 ↗</button></div><div class="result-grid"><article v-for="s in items" :key="s.school_id" class="feature-card"><span class="card-index">{{s.province}} · {{s.level}}</span><h2>{{s.name}}</h2><p>{{s.intro}}</p><RouterLink class="link" :to="`/schools/${s.school_id}`">查看画像 ↗</RouterLink></article></div></section></template>
